const TEAM_MEDIA = {
  "team-7": "data:image/webp;base64,",
  "team-8": "data:image/webp;base64,",
  "team-9": "data:image/webp;base64,"
};

const TOURNAMENT_MEDIA = {
  "pgl-abadia-2026": "data:image/webp;base64,"
};

const NEWS_MEDIA = {
  "pgl-2026-lineups": "data:image/webp;base64,"
};

function applyRecoveryMedia(content) {
  if (!content || typeof content !== "object") return content || {};
  (content.teams || []).forEach((team) => {
    if (!team.logo && TEAM_MEDIA[team.id]) team.logo = TEAM_MEDIA[team.id];
  });
  (content.tournaments || []).forEach((tournament) => {
    if (!tournament.logo && TOURNAMENT_MEDIA[tournament.id]) tournament.logo = TOURNAMENT_MEDIA[tournament.id];
  });
  (content.news || []).forEach((item) => {
    if (!item.image && NEWS_MEDIA[item.id]) item.image = NEWS_MEDIA[item.id];
  });
  return content;
}

module.exports = { applyRecoveryMedia };
